-- =============================================================================================
-- Hand-written below this line: payments tied to their posted ledger entries, receipt numbers,
-- allocations within a payment and an invoice of the same unit and party (serialised by
-- advisory locks), the one-time release of an allocation, payment intents completed once,
-- append-only provider events, the callback lookup policy, row-level security and grants.
-- See docs/architecture/DATA_MODEL.md section 6 (Payments).
-- =============================================================================================

-- ---------------------------------------------------------------------------------------------
-- payments
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "payments" ADD CONSTRAINT "payments_amount_positive" CHECK ("amount_minor" > 0);
ALTER TABLE "payments" ADD CONSTRAINT "payments_currency_format" CHECK ("currency" ~ '^[A-Z]{3}$');
ALTER TABLE "payments" ADD CONSTRAINT "payments_reference_trimmed"
  CHECK ("reference" IS NULL OR ("reference" = btrim("reference") AND length("reference") BETWEEN 1 AND 200));
ALTER TABLE "payments" ADD CONSTRAINT "payments_paid_by_consistent"
  CHECK (("paid_by" = 'TENANTS') = ("tenancy_id" IS NOT NULL));
ALTER TABLE "payments" ADD CONSTRAINT "payments_gateway_consistent"
  CHECK (("method" = 'GATEWAY') = ("payment_intent_id" IS NOT NULL));
-- Assigned by the insert trigger below.
ALTER TABLE "payments" ADD CONSTRAINT "payments_receipt_number_set"
  CHECK ("receipt_number" IS NOT NULL AND "receipt_number" >= 1);

-- A payment exists only with its posted PAYMENT entry of the same date and currency, which
-- credits exactly the amount to the unit's credit account. A gateway payment completes a pending
-- intent of the same unit, party, amount and currency. The receipt number is the property's next.
CREATE FUNCTION app_payment_insert_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  entry record;
  credited numeric;
  intent record;
BEGIN
  IF NEW."tenancy_id" IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM "tenancies" WHERE "id" = NEW."tenancy_id" AND "unit_id" = NEW."unit_id"
  ) THEN
    RAISE EXCEPTION 'the paying tenancy is not a tenancy of this unit' USING ERRCODE = 'check_violation';
  END IF;
  SELECT "status", "source", "entry_date", "currency" INTO entry
    FROM "journal_entries" WHERE "id" = NEW."journal_entry_id";
  IF entry."status" IS DISTINCT FROM 'POSTED' OR entry."source" <> 'PAYMENT'
     OR entry."entry_date" <> NEW."received_on" OR entry."currency" <> NEW."currency" THEN
    RAISE EXCEPTION 'a payment needs a posted payment entry of its date and currency'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT coalesce(sum(l."credit_minor") - sum(l."debit_minor"), 0) INTO credited
    FROM "journal_lines" l JOIN "ledger_accounts" a ON a."id" = l."account_id"
   WHERE l."entry_id" = NEW."journal_entry_id" AND a."system_key" = 'UNIT_CREDIT'
     AND l."unit_id" = NEW."unit_id";
  IF credited <> NEW."amount_minor" THEN
    RAISE EXCEPTION 'a payment entry must credit the amount to the unit''s credit'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."payment_intent_id" IS NOT NULL THEN
    SELECT * INTO intent FROM "payment_intents" WHERE "id" = NEW."payment_intent_id";
    IF intent."status" IS DISTINCT FROM 'PENDING' OR intent."unit_id" <> NEW."unit_id"
       OR intent."paid_by" <> NEW."paid_by" OR intent."tenancy_id" IS DISTINCT FROM NEW."tenancy_id"
       OR intent."amount_minor" <> NEW."amount_minor" OR intent."currency" <> NEW."currency" THEN
      RAISE EXCEPTION 'a gateway payment must complete a matching pending intent'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.payments:' || NEW."property_id"::text, 0));
  SELECT coalesce(max("receipt_number"), 0) + 1 INTO NEW."receipt_number"
    FROM "payments" WHERE "property_id" = NEW."property_id";
  RETURN NEW;
END
$$;

CREATE TRIGGER "payments_insert_check"
  BEFORE INSERT ON "payments"
  FOR EACH ROW EXECUTE FUNCTION app_payment_insert_check();

CREATE FUNCTION app_reject_payment_change() RETURNS trigger
  LANGUAGE plpgsql
  AS $$ BEGIN RAISE EXCEPTION 'payments never change; reverse them instead' USING ERRCODE = 'insufficient_privilege'; END $$;

CREATE TRIGGER "payments_immutable"
  BEFORE UPDATE OR DELETE ON "payments"
  FOR EACH ROW EXECUTE FUNCTION app_reject_payment_change();

-- ---------------------------------------------------------------------------------------------
-- payment_allocations
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "payment_allocations" ADD CONSTRAINT "payment_allocations_amount_positive"
  CHECK ("amount_minor" > 0);
ALTER TABLE "payment_allocations" ADD CONSTRAINT "payment_allocations_release_consistent"
  CHECK (("released_at" IS NULL) = ("release_entry_id" IS NULL)
         AND ("released_by_user_id" IS NULL OR "released_at" IS NOT NULL));

-- An allocation applies part of a payment to an issued invoice of the same unit (composite keys)
-- and the same party, never more than what is left of either. Advisory locks on the payment and
-- then the invoice serialise concurrent allocations and releases.
CREATE FUNCTION app_payment_allocation_insert_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  pay record;
  inv record;
  used numeric;
BEGIN
  IF NEW."released_at" IS NOT NULL THEN
    RAISE EXCEPTION 'an allocation is created unreleased' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.payment:' || NEW."payment_id"::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.invoice:' || NEW."invoice_id"::text, 0));
  SELECT "paid_by", "tenancy_id", "amount_minor" INTO pay FROM "payments" WHERE "id" = NEW."payment_id";
  SELECT "status", "bill_to", "tenancy_id", "total_minor" INTO inv FROM "invoices" WHERE "id" = NEW."invoice_id";
  IF inv."status" IS DISTINCT FROM 'ISSUED' THEN
    RAISE EXCEPTION 'payments are allocated to issued invoices only' USING ERRCODE = 'check_violation';
  END IF;
  IF pay."paid_by" <> inv."bill_to" OR pay."tenancy_id" IS DISTINCT FROM inv."tenancy_id" THEN
    RAISE EXCEPTION 'a payment pays only invoices addressed to whoever made it'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT coalesce(sum("amount_minor"), 0) INTO used FROM "payment_allocations"
   WHERE "payment_id" = NEW."payment_id" AND "released_at" IS NULL;
  IF used + NEW."amount_minor" > pay."amount_minor" THEN
    RAISE EXCEPTION 'the allocation is more than what is left of the payment'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT coalesce(sum("amount_minor"), 0) INTO used FROM "payment_allocations"
   WHERE "invoice_id" = NEW."invoice_id" AND "released_at" IS NULL;
  IF used + NEW."amount_minor" > inv."total_minor" THEN
    RAISE EXCEPTION 'the allocation is more than what is left to pay on the invoice'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM "journal_entries"
     WHERE "id" = NEW."journal_entry_id" AND "status" = 'POSTED' AND "source" = 'ALLOCATION'
  ) THEN
    RAISE EXCEPTION 'an allocation needs a posted allocation entry' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "payment_allocations_insert_check"
  BEFORE INSERT ON "payment_allocations"
  FOR EACH ROW EXECUTE FUNCTION app_payment_allocation_insert_check();

-- The only change: releasing, once, with a posted allocation entry moving the money back.
CREATE FUNCTION app_payment_allocation_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.payment:' || OLD."payment_id"::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.invoice:' || OLD."invoice_id"::text, 0));
  IF OLD."released_at" IS NOT NULL OR NEW."released_at" IS NULL
     OR (NEW."organisation_id", NEW."property_id", NEW."unit_id", NEW."payment_id", NEW."invoice_id",
         NEW."amount_minor", NEW."journal_entry_id", NEW."allocated_by_user_id", NEW."created_at")
        IS DISTINCT FROM
        (OLD."organisation_id", OLD."property_id", OLD."unit_id", OLD."payment_id", OLD."invoice_id",
         OLD."amount_minor", OLD."journal_entry_id", OLD."allocated_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'allocation % can only be released, once', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM "journal_entries"
     WHERE "id" = NEW."release_entry_id" AND "status" = 'POSTED' AND "source" = 'ALLOCATION'
  ) THEN
    RAISE EXCEPTION 'a release needs a posted allocation entry' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "payment_allocations_guard"
  BEFORE UPDATE ON "payment_allocations"
  FOR EACH ROW EXECUTE FUNCTION app_payment_allocation_guard();

-- ---------------------------------------------------------------------------------------------
-- payment_intents: completed once; SUCCEEDED only with its payment recorded.
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "payment_intents" ADD CONSTRAINT "payment_intents_amount_positive" CHECK ("amount_minor" > 0);
ALTER TABLE "payment_intents" ADD CONSTRAINT "payment_intents_currency_format" CHECK ("currency" ~ '^[A-Z]{3}$');
ALTER TABLE "payment_intents" ADD CONSTRAINT "payment_intents_provider_format"
  CHECK ("provider" ~ '^[a-z][a-z0-9_-]{1,30}$');
ALTER TABLE "payment_intents" ADD CONSTRAINT "payment_intents_reference_length"
  CHECK (length("provider_reference") BETWEEN 8 AND 200);
ALTER TABLE "payment_intents" ADD CONSTRAINT "payment_intents_paid_by_consistent"
  CHECK (("paid_by" = 'TENANTS') = ("tenancy_id" IS NOT NULL));
ALTER TABLE "payment_intents" ADD CONSTRAINT "payment_intents_completion_consistent"
  CHECK (("status" = 'PENDING') = ("completed_at" IS NULL) AND "expires_at" > "created_at");

CREATE FUNCTION app_payment_intent_insert_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NEW."status" <> 'PENDING' THEN
    RAISE EXCEPTION 'payment intents start pending' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."tenancy_id" IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM "tenancies" WHERE "id" = NEW."tenancy_id" AND "unit_id" = NEW."unit_id"
  ) THEN
    RAISE EXCEPTION 'the paying tenancy is not a tenancy of this unit' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "payment_intents_insert_check"
  BEFORE INSERT ON "payment_intents"
  FOR EACH ROW EXECUTE FUNCTION app_payment_intent_insert_check();

CREATE FUNCTION app_payment_intent_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF OLD."status" <> 'PENDING'
     OR (NEW."organisation_id", NEW."property_id", NEW."unit_id", NEW."paid_by", NEW."tenancy_id",
         NEW."amount_minor", NEW."currency", NEW."provider", NEW."provider_reference", NEW."expires_at",
         NEW."created_by_user_id", NEW."created_at")
        IS DISTINCT FROM
        (OLD."organisation_id", OLD."property_id", OLD."unit_id", OLD."paid_by", OLD."tenancy_id",
         OLD."amount_minor", OLD."currency", OLD."provider", OLD."provider_reference", OLD."expires_at",
         OLD."created_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'payment intent % can only be completed, once', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" = 'SUCCEEDED' AND NOT EXISTS (
    SELECT 1 FROM "payments" WHERE "payment_intent_id" = NEW."id"
  ) THEN
    RAISE EXCEPTION 'payment intent % succeeds only with its payment recorded', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "payment_intents_guard"
  BEFORE UPDATE ON "payment_intents"
  FOR EACH ROW EXECUTE FUNCTION app_payment_intent_guard();

-- ---------------------------------------------------------------------------------------------
-- payment_provider_events: append-only for every role.
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "payment_provider_events" ADD CONSTRAINT "payment_provider_events_provider_format"
  CHECK ("provider" ~ '^[a-z][a-z0-9_-]{1,30}$');
ALTER TABLE "payment_provider_events" ADD CONSTRAINT "payment_provider_events_text"
  CHECK (length("provider_event_id") BETWEEN 1 AND 200 AND length("type") BETWEEN 1 AND 100
         AND length("outcome") BETWEEN 1 AND 40);

CREATE FUNCTION app_reject_payment_event_change() RETURNS trigger
  LANGUAGE plpgsql
  AS $$ BEGIN RAISE EXCEPTION 'payment_provider_events is append-only' USING ERRCODE = 'insufficient_privilege'; END $$;

CREATE TRIGGER "payment_provider_events_append_only"
  BEFORE UPDATE OR DELETE ON "payment_provider_events"
  FOR EACH ROW EXECUTE FUNCTION app_reject_payment_event_change();

CREATE TRIGGER "payments_no_truncate"
  BEFORE TRUNCATE ON "payments"
  FOR EACH STATEMENT EXECUTE FUNCTION app_reject_ledger_truncate();
CREATE TRIGGER "payment_allocations_no_truncate"
  BEFORE TRUNCATE ON "payment_allocations"
  FOR EACH STATEMENT EXECUTE FUNCTION app_reject_ledger_truncate();
CREATE TRIGGER "payment_provider_events_no_truncate"
  BEFORE TRUNCATE ON "payment_provider_events"
  FOR EACH STATEMENT EXECUTE FUNCTION app_reject_ledger_truncate();

-- ---------------------------------------------------------------------------------------------
-- Callback lookup. A provider callback arrives with no tenant context. As for invitation tokens
-- (migration 20261108160000), the SELECT policy also admits the one intent whose
-- "<provider>:<provider reference>" the caller presents in a transaction-local setting. The API
-- sets it only after verifying the callback's signature.
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app_current_payment_reference() RETURNS text
  LANGUAGE sql STABLE PARALLEL SAFE
  AS $$ SELECT NULLIF(current_setting('app.payment_reference', true), '') $$;

GRANT EXECUTE ON FUNCTION app_current_payment_reference() TO veyra_app;

-- ---------------------------------------------------------------------------------------------
-- Row-level security: tenant context only, except the callback lookup above.
-- ---------------------------------------------------------------------------------------------
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['payments', 'payment_allocations', 'payment_intents', 'payment_provider_events'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
  END LOOP;
  FOREACH t IN ARRAY ARRAY['payments', 'payment_allocations', 'payment_provider_events'] LOOP
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
  END LOOP;
  FOREACH t IN ARRAY ARRAY['payment_allocations', 'payment_intents'] LOOP
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
END
$$;

CREATE POLICY "payment_intents_select" ON "payment_intents" FOR SELECT
  USING (
    "organisation_id" = app_current_organisation_id()
    OR ("provider" || ':' || "provider_reference") = app_current_payment_reference()
  );

-- ---------------------------------------------------------------------------------------------
-- Least privilege: payments and provider events are insert-only; allocations and intents change
-- only as the triggers allow; nothing is deleted.
-- ---------------------------------------------------------------------------------------------
REVOKE ALL ON "payments", "payment_allocations", "payment_intents", "payment_provider_events" FROM PUBLIC;
GRANT SELECT, INSERT ON "payments", "payment_provider_events" TO veyra_app;
GRANT SELECT, INSERT, UPDATE ON "payment_allocations", "payment_intents" TO veyra_app;
